            current = stack.pop()
            if not visited[current]:
                visited[current] = True
                if current == target:
                    return True
                for neighbor in self.graph[current]:
                    if not visited[neighbor]:
                        stack.append(neighbor)
        return False

    def has_path(self, start, target):
        return self.dfs(start, target, visited=None)
