Here's a simple implementation of BFS for a graph represented as an adjacency list:

```python
from collections import deque

class Graph:
    def __init__(self):
        self.graph = {}

    def add_edge(self, start, end):
        if start not in self.graph:
            self.graph[start] = []
        self.graph[start].append(end)

    def bfs(self, start_node, goal_node):
        if start_node not in self.graph or goal_node not in self.graph:
            return None

        visited = set()
        queue = deque([start_node])

        while queue:
            current_node = queue.popleft()
            visited.add(current_node)

            if current_node == goal_node:
                return current_node

            for neighbor in self.graph.get(current_node, []):
                if neighbor not in visited:
                    queue.append(neighbor)

        return None

# Example usage:
if __name__ == "__main__":
    g = Graph()
    g.add_edge('A', 'B')
    g.add_edge('A', 'C')
    g.add_edge('B', 'D')
    g.add_edge('B', 'E')
    g.add_edge('C', 'F')

    start_node = 'A'
    goal_node = 'E'

    path = g.bfs(start_node, goal_node)

    if path:
        print(f"Path from {start_node} to {goal_node}: {' -> '.join(path)}")
    else:
